#!/bin/sh
set -eu

[ "$#" -eq 5 ] || exit 2
launcher_command=$1
unset P11SCOPE_PREPARED_STABLE_CARGO \
    P11SCOPE_PREPARED_STABLE_RUSTC \
    P11SCOPE_PREPARED_BPF_CARGO \
    P11SCOPE_PREPARED_BPF_RUSTC
P11SCOPE_PREPARED_STABLE_CARGO=$2
P11SCOPE_PREPARED_STABLE_RUSTC=$3
P11SCOPE_PREPARED_BPF_CARGO=$4
P11SCOPE_PREPARED_BPF_RUSTC=$5
. "$launcher_command"
